import { execFileSync, spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { expect, it } from "vitest";
import {
  BATCH_GENERATORS,
  changedFiles,
  commitMessage,
  isRegenerated,
  notGenerated,
  REGENERATED_SUBJECT,
} from "../scripts/batch-regenerate.ts";
import { loadYamlFile, workflowString } from "./helpers/releaseWorkflows.ts";
import { scratchDir } from "./helpers/scratchDirs";

/**
 * The captain's pick in the daily velocity review: "Have each batch
 * regenerate the phone's generated files itself, as its own commit, before
 * its checks run." A batch's first job runs the project's generators on the
 * batch's version (scripts/batch-regenerate.ts), and the job after it
 * pushes what they changed as one commit on the batch branch, which the app
 * takes only when every file it changes is marked generated by the batch's
 * own .gitattributes (src/core/batches/combine.ts, `generatedOnTop`).
 */

function project(dir: string) {
  const gitEnv = {
    PATH: process.env.PATH,
    HOME: dir,
    GIT_CONFIG_GLOBAL: "/dev/null",
    GIT_CONFIG_NOSYSTEM: "1",
  };
  const git = (cwd: string, ...args: string[]) =>
    execFileSync("git", ["-c", "user.name=batch", "-c", "user.email=batch@localhost", ...args], {
      cwd,
      env: gitEnv,
      encoding: "utf8",
    }).trim();
  const write = (root: string, path: string, text: string) => {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), text);
  };
  return { gitEnv, git, write };
}

it("names the changed files the batch's own .gitattributes does not mark generated, whatever the generators wrote there", () => {
  const dir = scratchDir("infinitary-batch-regenerate-");
  const { git, write } = project(dir);
  const root = join(dir, "work");
  mkdirSync(root);
  git(root, "init", "-q", "-b", "main");
  write(root, ".gitattributes", "ios/**/*.generated.* linguist-generated\n");
  write(root, "ios/App/Words.generated.swift", "let words = 1\n");
  write(root, "src/words.ts", "export const words = 1;\n");
  git(root, "add", "-A");
  git(root, "commit", "-q", "-m", "chore: start");

  // A generator rewrites a generated file, adds one in a folder with a space, and touches a source file.
  write(root, "ios/App/Words.generated.swift", "let words = 2\n");
  write(root, "ios/New Folder/Seats.generated.json", "[]\n");
  write(root, "src/words.ts", "export const words = 2;\n");
  // A .gitattributes written in the working copy marks nothing: the batch's own version decides.
  write(root, ".gitattributes", "* linguist-generated\n");

  const files = changedFiles(root);
  expect(files.sort()).toEqual(
    [
      ".gitattributes",
      "ios/App/Words.generated.swift",
      "ios/New Folder/Seats.generated.json",
      "src/words.ts",
    ].sort(),
  );
  expect(notGenerated(root, files).sort()).toEqual([".gitattributes", "src/words.ts"]);
  expect(
    notGenerated(root, ["ios/App/Words.generated.swift", "ios/New Folder/Seats.generated.json"]),
  ).toEqual([]);
});

it("words the commit with the trailer that keeps its own version from being regenerated again", () => {
  const message = commitMessage(["ios/App/Words.generated.swift"]);
  expect(message.split("\n")[0]).toBe(REGENERATED_SUBJECT);
  expect(message).toContain("- ios/App/Words.generated.swift");
  expect(isRegenerated(message)).toBe(true);
  expect(isRegenerated("fix(phone): mention Batch-regenerated: phone in passing")).toBe(false);
});

// INF-6259's weekly audit, the captain's pick "Batch regenerates all
// generated files: ... it would also rebuild the app parts list": two changes
// in one batch left the app parts list out of step, and pnpm check held the
// batch. The phone's card bundle carries the app's parts, so their generator
// runs first, and the app takes the commit only when the project marks every
// file it writes generated.
it("regenerates the app parts list before the phone's card bundle, and the project marks what it writes generated", () => {
  const parts = BATCH_GENERATORS.indexOf("scripts/generate-runbook-parts.ts");
  expect(parts).toBeGreaterThanOrEqual(0);
  expect(parts).toBeLessThan(BATCH_GENERATORS.indexOf("scripts/generate-phone-cards.ts"));
  // What scripts/generate-runbook-parts.ts writes.
  const written = [
    "src/shared/appParts.generated.json",
    "resources/runbooks/architecture/skills/advanced-architecture/parts/map.html",
    "resources/runbooks/architecture/skills/advanced-architecture/parts/map-page.html",
  ];
  expect(notGenerated(process.cwd(), written)).toEqual([]);
});

type Step = { run: string; env: Record<string, string> };

it("pushes the regenerated files as one commit on the batch branch, then ends once the app's own push moves the branch on", () => {
  const dir = scratchDir("infinitary-batch-push-regenerated-");
  const { gitEnv, git, write } = project(dir);
  // Where the project lives, a batch branch on it, and the job's checkout of the batch's version.
  const bare = join(dir, "project.git");
  git(dir, "init", "-q", "--bare", "-b", "main", bare);
  const seed = join(dir, "seed");
  git(dir, "clone", "-q", bare, seed);
  write(seed, "ios/App/Words.generated.swift", "let words = 1\n");
  git(seed, "add", "-A");
  git(seed, "commit", "-q", "-m", "feat(cards): two changes in one batch");
  git(seed, "push", "-q", "origin", "HEAD:refs/heads/infinitary-batch/one");
  const head = git(seed, "rev-parse", "HEAD");
  const workspace = join(dir, "workspace");
  git(dir, "clone", "-q", "--branch", "infinitary-batch/one", bare, workspace);

  // What the regenerate job handed on: the generators' difference and the commit's words.
  write(seed, "ios/App/Words.generated.swift", "let words = 2\n");
  const files = join(dir, "regenerated");
  mkdirSync(files);
  writeFileSync(
    join(files, "regenerated.patch"),
    `${execFileSync("git", ["diff", "--binary"], { cwd: seed, env: gitEnv, encoding: "utf8" })}`,
  );
  writeFileSync(join(files, "message.txt"), commitMessage(["ios/App/Words.generated.swift"]));
  git(seed, "checkout", "-q", "--", ".");

  // The app's push of the regenerated commit, as the job's first wait sees it:
  // the step's `sleep`, as a shell function, since a login's own shell
  // set-up may set PATH again.
  const appPush = [
    `git -C "${seed}" fetch -q origin infinitary-batch/one`,
    `git -C "${seed}" checkout -q FETCH_HEAD`,
    `git -C "${seed}" -c user.name=app -c user.email=app@localhost commit -q --allow-empty -m "the app's push"`,
    `git -C "${seed}" push -q --force origin HEAD:refs/heads/infinitary-batch/one`,
  ].join(" && ");

  const job = (
    loadYamlFile(".github/workflows/batch-checks.yml") as {
      jobs: { "push-regenerated": { steps: Partial<Step>[] } };
    }
  ).jobs["push-regenerated"];
  const step = job.steps.find((candidate) => candidate.run) as Step;
  const contexts = {
    inputs: { trigger: "Merge batch", head },
    github: { head_ref: "infinitary-batch/one" },
    runner: { temp: dir },
  };
  const env = Object.fromEntries(
    Object.entries(step.env).map(([name, value]) => [name, workflowString(value, contexts)]),
  );
  // The shell GitHub Actions gives a run step that names none.
  const ran = spawnSync("bash", ["-e", "-c", step.run], {
    timeout: 60_000,
    cwd: workspace,
    env: { ...gitEnv, ...env, "BASH_FUNC_sleep%%": `() { ${appPush}; }` },
    encoding: "utf8",
  });
  expect(ran.status, ran.stderr).toBe(0);
  expect(ran.stdout).toContain("The branch moved on to");

  // The regenerated commit sits on the batch's version with the generated file alone.
  const pushed = git(bare, "rev-parse", "infinitary-batch/one~1");
  expect(git(bare, "rev-parse", `${pushed}^`)).toBe(head);
  expect(git(bare, "diff", "--name-only", head, pushed)).toBe("ios/App/Words.generated.swift");
  expect(git(bare, "show", `${pushed}:ios/App/Words.generated.swift`)).toBe("let words = 2");
  expect(git(bare, "log", "-1", "--format=%an", pushed)).toBe("github-actions[bot]");
  expect(isRegenerated(git(bare, "log", "-1", "--format=%B", pushed))).toBe(true);
});
